    try {
        fileKeyStore.setAttributes(unacceptableAttributes);
        fail("Exception not thrown");
    } catch (IllegalConfigurationException e) {
        String message = e.getMessage();
        assertTrue("Exception text not as unexpected:" + message, message.contains(String.format("Cannot find a certificate with alias '%s' in key store", unknownAlias)));
    }
    assertNull("Unexpected alias value after failed change", fileKeyStore.getCertificateAlias());
    Map<String, Object> changedAttributes = new HashMap<>();
    changedAttributes.put(FileKeyStore.CERTIFICATE_ALIAS, TLS_RESOURCE.getPrivateKeyAlias());
    fileKeyStore.setAttributes(changedAttributes);
    assertEquals("Unexpected alias value after change that is expected to be successful", TLS_RESOURCE.getPrivateKeyAlias(), fileKeyStore.getCertificateAlias());
}

