    applicationHeaders.put("testProperty", "testValue");
    applicationHeaders.put("list", Arrays.asList("a", 1, 2.0));
    applicationHeaders.put("map", Collections.singletonMap("mapKey", "mapValue"));
    MessageProperties messageProperties = new MessageProperties(10, UUID.randomUUID(), "abc".getBytes(UTF_8), new ReplyTo("amq.direct", "test"), "text/plain", "identity", "cba".getBytes(UTF_8), "app".getBytes(UTF_8), applicationHeaders);
