        try (ByteArrayOutputStream bos = new ByteArrayOutputStream();
            DataOutputStream dos = new DataOutputStream(bos)) {
            dos.writeByte(0);
            /* flags */
            dos.writeByte(4);
            /* segment type - undefined value in 0-10 */
            dos.writeShort(12);
            /* size */
            dos.writeByte(0);
            dos.writeByte(0);
            /* track */
            dos.writeShort(0);
            /* channel */
            dos.writeByte(0);
            dos.writeByte(0);
            dos.writeByte(0);
            dos.writeByte(0);
            transport.sendBytes(bos.toByteArray());
        }
        transport.flush();
        transport.assertNoMoreResponsesAndChannelClosed();
    }
}

