        ContentHeaderBody header = interaction.consumeResponse(ContentHeaderBody.class).getLatestResponse(ContentHeaderBody.class);
        assertThat(header.getBodySize(), is(equalTo((long) content2Bytes.length)));
        BasicContentHeaderProperties properties = header.getProperties();
        Map<String, Object> receivedHeaders = new HashMap<>(properties.getHeadersAsMap());
        assertThat(receivedHeaders.isEmpty(), is(equalTo(true)));
        String receivedContent = interaction.consumeResponse(ContentBody.class).getLatestResponseContentBodyAsString();
        assertThat(receivedContent, is(equalTo(content2)));
        interaction.channel().close().consumeResponse(ChannelCloseOkBody.class, ChannelFlowOkBody.class);
    }
}

