@Test
@SpecificationTest(section = "2.6.12 Transferring A Message", description = "The delivery-tag MUST be unique amongst all deliveries" + " that could be considered unsettled by either end of the link.")
public void transferMessagesWithTheSameDeliveryTagOnSeparateLinksBelongingToTheSameSession() throws Exception {
    final String[] contents = Utils.createTestMessageContents(2, getTestName());
    try (final FrameTransport transport = new FrameTransport(getBrokerAdmin()).connect()) {
        final UnsignedInteger link1Handle = UnsignedInteger.ONE;
        final UnsignedInteger link2Handle = UnsignedInteger.valueOf(2);
        final Binary deliveryTag = new Binary("deliveryTag".getBytes(StandardCharsets.UTF_8));
        final Interaction interaction = transport.newInteraction();
        interaction.negotiateOpen().begin().consumeResponse(Begin.class).attachName("test1").attachRole(Role.SENDER).attachTargetAddress(BrokerAdmin.TEST_QUEUE_NAME).attachSndSettleMode(SenderSettleMode.UNSETTLED).attachRcvSettleMode(ReceiverSettleMode.FIRST).attachHandle(link1Handle).attach().consumeResponse(Attach.class).consumeResponse(Flow.class).assertLatestResponse(Flow.class, this::assumeSufficientCredits).attachName("test2").attachHandle(link2Handle).attach().consumeResponse(Attach.class).consumeResponse(Flow.class).assertLatestResponse(Flow.class, this::assumeSufficientCredits).transferHandle(link1Handle).transferPayloadData(contents[0]).transferDeliveryTag(deliveryTag).transferDeliveryId(UnsignedInteger.ZERO).transfer().transferHandle(link2Handle).transferDeliveryId(UnsignedInteger.ONE).transferPayloadData(contents[1]).transferDeliveryTag(deliveryTag).transfer();
        final Disposition disposition1 = interaction.consume(Disposition.class, Flow.class);
        final UnsignedInteger first = disposition1.getFirst();
        final UnsignedInteger last = disposition1.getLast();
        assertThat(first, anyOf(is(UnsignedInteger.ZERO), is(UnsignedInteger.ONE)));
        assertThat(last, anyOf(nullValue(), is(UnsignedInteger.ZERO), is(UnsignedInteger.ONE)));
        if (last == null || first.equals(last)) {
            final Disposition disposition2 = interaction.consume(Disposition.class, Flow.class);
            assertThat(disposition2.getFirst(), anyOf(is(UnsignedInteger.ZERO), is(UnsignedInteger.ONE)));
