@Test
public void virtualHostStatisticsReporting() throws Exception {
    String hostLogDownloadUrl = configureLogger(true);
    Connection conn = getConnection();
    try {
        getBrokerAdmin().createQueue(QUEUE1_NAME);
        Session session = conn.createSession(true, Session.SESSION_TRANSACTED);
        // Enable Virtual Host Statistics Reporting
        final Map<String, Object> arguments = new HashMap<>();
        arguments.put(QueueManagingVirtualHost.STATISTICS_REPORTING_PERIOD, STATISTICS_REPORTING_PERIOD_IN_SEC);
        Map<String, String> context = singletonMap("qpid.queue.statisticsReportPattern", "${ancestor:virtualhost:name}/${ancestor:queue:name}: " + "queueDepthMessages=${queueDepthMessages}, " + "queueDepthBytes=${queueDepthBytes:byteunit}");
        arguments.put(ConfiguredObject.CONTEXT, context);
        getHelper().submitRequest("virtualhost", "POST", arguments, SC_OK);
        assertThat("Pre-enqueue queue1 statistics report not found", countLogFileMatches(hostLogDownloadUrl, String.format("%s/%s: queueDepthMessages=0, queueDepthBytes=0 B", getVirtualHost(), QUEUE1_NAME), LOG_TIMEOUT_IN_MS), is(greaterThan(0)));
        // Enqueue a single message to queue 1
        Utils.sendMessages(session, session.createQueue(QUEUE1_NAME), 1);
        assertThat("Post-enqueue queue1 statistics report not found", countLogFileMatches(hostLogDownloadUrl, String.format("%s/%s: queueDepthMessages=1", getVirtualHost(), QUEUE1_NAME), LOG_TIMEOUT_IN_MS), is(greaterThan(0)));
        getBrokerAdmin().createQueue(QUEUE2_NAME);
        assertThat("Initial queue2 statistics report not found", countLogFileMatches(hostLogDownloadUrl, String.format("%s/%s: queueDepthMessages=0, queueDepthBytes=0 B", getVirtualHost(), QUEUE2_NAME), LOG_TIMEOUT_IN_MS), is(greaterThan(0)));
        // Override the statistic report for queue2 only
        Map<String, String> queue2Context = singletonMap("qpid.queue.statisticsReportPattern", "${ancestor:virtualhost:name}/${ancestor:queue:name}: " + "oldestMessageAge=${oldestMessageAge:duration}");
        getHelper().submitRequest(String.format("queue/%s", QUEUE2_NAME), "POST", singletonMap(ConfiguredObject.CONTEXT, queue2Context), SC_OK);
        assertThat("Post-enqueue queue2 statistics report not found", countLogFileMatches(hostLogDownloadUrl, String.format("%s/%s: oldestMessageAge=PT", getVirtualHost(), QUEUE2_NAME), LOG_TIMEOUT_IN_MS), is(greaterThan(0)));
    } finally {
        conn.close();
    }
}

